create or replace TRIGGER APP_EXTENSION.VVRE_PROJ_ELEMENT_INSERT_UPD_TRG
FOR INSERT OR UPDATE OF VL_ELEMENTO
ON VVRE_PROJ_ELEMENT
COMPOUND TRIGGER

    TYPE t_proj_tab IS TABLE OF VVRE_PROJ_ELEMENT.NR_SEQ_PROJETO%TYPE;
    v_projetos t_proj_tab := t_proj_tab();

BEFORE EACH ROW IS
BEGIN
    -- Validar valor positivo
    IF :NEW.VL_ELEMENTO <= 0 THEN
        raise_application_error(-20011,'O valor do elemento deve ser maior que zero.');
    END IF;

    -- Guardar projeto afectado
    v_projetos.EXTEND;
    v_projetos(v_projetos.COUNT) :=
        NVL(:NEW.NR_SEQ_PROJETO, :OLD.NR_SEQ_PROJETO);

END BEFORE EACH ROW;


AFTER STATEMENT IS
    v_saldo_projeto   NUMBER;
    v_total_elemento  NUMBER;
BEGIN

    FOR i IN 1 .. v_projetos.COUNT LOOP

        -- Obtener saldo disponible
        SELECT NVL(VL_SALDO,0)
        INTO v_saldo_projeto
        FROM VVRE_PROJ_COMPRAS
        WHERE NR_SEQUENCIA = v_projetos(i)
        FOR UPDATE;  -- evita concurrencia

        -- Sumar todos los elementos ya persistidos
        SELECT NVL(SUM(VL_ELEMENTO),0)
        INTO v_total_elemento
        FROM VVRE_PROJ_ELEMENT
        WHERE NR_SEQ_PROJETO = v_projetos(i);

        -- Validar
        IF v_total_elemento > v_saldo_projeto THEN
            raise_application_error(-20011,'A soma dos elementos excede o saldo do projeto.');
        END IF;

    END LOOP;

END AFTER STATEMENT;

END;
/

